import fs from 'node:fs';import path from 'node:path';import {juanTotals,MONTHS} from '../server/features/prevision/JuanExcel.js';
const folder=path.join(process.env.USERPROFILE,'Downloads/updates/revision-gastos-20261004/comparacion-2026'),original=JSON.parse(fs.readFileSync(path.join(folder,'source-2026.json'),'utf8')),current=JSON.parse(fs.readFileSync(path.join(folder,'current-2026.json'),'utf8'));
const differences=[],added=[],monthly=[];
for(const src of original){const cur=current.sheets.find(s=>s.bank===src.bank);for(const section of ['income','payments']){
 for(const row of src[section]){const now=cur[section].find(r=>r.id===row.id);const parts=cur[section].filter(r=>r.id.startsWith(row.id+':')&&r.cardPart);for(let month=1;month<=12;month++)for(const kind of ['actual','forecast']){const si=src.columns.findIndex(c=>c.month===month&&c.kind===kind),ci=cur.columns.findIndex(c=>c.month===month&&c.kind===kind);if(si<0||ci<0)continue;const old=row.values[si]||0,value=(now?.values[ci]||0)+parts.reduce((n,r)=>n+(r.values[ci]||0),0);if(old!==value)differences.push({bank:src.bank,section,rowId:row.id,label:row.label,month,kind,excel:old/100,current:value/100,difference:(value-old)/100});}
  if(now&&row.day!==now.day)differences.push({bank:src.bank,section,rowId:row.id,label:row.label,type:'day',excel:row.day,current:now.day});
 }
 for(const r of cur[section].filter(r=>!src[section].some(o=>o.id===r.id)&&!r.cardPart&&r.values.some(v=>v))){added.push({bank:src.bank,section,id:r.id,label:r.label,months:cur.columns.flatMap((c,i)=>r.values[i]?[{month:c.month,kind:c.kind,amount:r.values[i]/100}]:[])});}
 }
 const a=juanTotals(src),b=juanTotals(cur);for(let month=1;month<=12;month++){const idx=src.columns.flatMap((c,i)=>c.month===month?[i]:[]),jdx=cur.columns.flatMap((c,i)=>c.month===month?[i]:[]),sum=(v,is)=>is.reduce((n,i)=>n+v[i],0)/100;monthly.push({bank:src.bank,month,excelIncome:sum(a.income,idx),currentIncome:sum(b.income,jdx),excelPayments:sum(a.payments,idx),currentPayments:sum(b.payments,jdx),differenceIncome:sum(b.income,jdx)-sum(a.income,idx),differencePayments:sum(b.payments,jdx)-sum(a.payments,idx)});}
}
const result={differences,added,monthly,incomeDifferences:current.incomeDifferences};fs.writeFileSync(path.join(folder,'differences.json'),JSON.stringify(result,null,2));console.log(JSON.stringify(result));
const money=n=>Number(n).toLocaleString('es-ES',{minimumFractionDigits:2,maximumFractionDigits:2});let report='COMPARACION EXCEL ORIGINAL DE JUAN CON PREVISION ACTUAL 2026\n\nSe comparan ambas pestanas 2026; realizado y previsto por separado. No se modifica el Excel fuente. Diferencias de fecha son dias orientativos de fila; pagos reales conservan sus fechas bancarias.\n\n';
for(const m of monthly.filter(m=>m.differenceIncome||m.differencePayments))report+=`${m.bank} ${MONTHS[m.month-1]}: ingresos Excel ${money(m.excelIncome)} / actuales ${money(m.currentIncome)}; pagos Excel ${money(m.excelPayments)} / actuales ${money(m.currentPayments)}\n`;
report+='\nDIFERENCIAS POR FILA Y MES\n';for(const d of differences)report+=d.type==='day'?`${d.bank} ${d.label}: dia Excel ${d.excel} / actual ${d.current}\n`:`${d.bank} ${MONTHS[d.month-1]} ${d.kind==='forecast'?'previsto':'realizado'} ${d.label}: Excel ${money(d.excel)} / actual ${money(d.current)} / diferencia ${money(d.difference)}\n`;
report+='\nFILAS ADICIONALES\n';for(const d of added)report+=`${d.bank} ${d.label}: ${d.months.map(m=>`${MONTHS[m.month-1]} ${m.kind} ${money(m.amount)}`).join('; ')}\n`;
fs.writeFileSync(path.join(folder,'Comparacion-2026.txt'),report);
